import sys
input = sys.stdin.read().split()
n = int(input[0])
k = int(input[1])
if k > n * (n + 1) // 2:
    print(-1)
else:
    matrix = [[0] * n for _ in range(n)]
    count = 0
    for i in range(n):
        for j in range(i + 1):
            if count < k:
                matrix[i][j] = 1
                matrix[j][i] = 1
                count += 1
    for row in matrix:
        print(' '.join(map(str, row)))
